import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure target_state has the right structure even if empty
    if len(target_state) == 0:
        target_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        target_state = target_state.astype({
            "order_id": "int64",
            "status": "str",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Ensure cdc_events has the right structure even if empty
    if len(cdc_events) == 0:
        cdc_events = pd.DataFrame(columns=["seq", "order_id", "op", "status", "amount", "event_ts"])
        cdc_events = cdc_events.astype({
            "seq": "int64",
            "order_id": "int64",
            "op": "str",
            "status": "str",
            "amount": "float64",
            "event_ts": "datetime64[us]"
        })

    # Step 1: Remove duplicates by seq (at-least-once delivery)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Build a dict of current state for fast lookup
    state_dict = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        state_dict[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Step 3: Apply events in seq order, with replay guard per order
    # Track which orders had events and their final operation
    order_last_event = {}  # order_id -> (seq, op)

    # Sort by seq to process in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    for _, event in cdc_events.iterrows():
        seq = event["seq"]
        order_id = event["order_id"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Replay guard: skip if order has a row and seq <= last_seq
        if order_id in state_dict and seq <= state_dict[order_id]["last_seq"]:
            continue

        # Track that this order had an event
        order_last_event[order_id] = (seq, op)

        if op in ["I", "U"]:
            if order_id in state_dict:
                # Update existing row
                state_dict[order_id]["status"] = status
                # For 'U' with NULL amount, preserve existing amount
                if not pd.isna(amount) or op == "I":
                    state_dict[order_id]["amount"] = amount
                state_dict[order_id]["last_seq"] = seq
            else:
                # Create new row (both 'I' and 'U' on missing order create it)
                state_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
        elif op == "D":
            # Delete the row
            if order_id in state_dict:
                del state_dict[order_id]

    # Step 4: Build new_state from state_dict
    new_state_rows = []
    for order_id, state in state_dict.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": state["status"],
            "amount": state["amount"],
            "last_seq": state["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "str",
            "amount": "float64",
            "last_seq": "int64"
        })
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "str",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Step 5: Build tombstones
    # An order gets a tombstone if it had a row (in target_state or created)
    # and its last applied event is 'D'
    tombstone_rows = []
    for order_id, (seq, op) in order_last_event.items():
        if op == "D":
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": seq
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
